'use strict';

// MODULES //

var tape = require( 'tape' );
var isSameFloat64Array = require( '@stdlib/assert/is-same-float64array' );
var Float64Array = require( '@stdlib/array/float64' );
var scalar2ndarray = require( '@stdlib/ndarray/from-scalar' );
var getData = require( '@stdlib/ndarray/data-buffer' );
var ndarray = require( '@stdlib/ndarray/base/ctor' );
var dreplicate = require( './../lib' );


// FUNCTIONS //

/**
* Returns a one-dimensional ndarray.
*
* @private
* @param {Float64Array} buffer - underlying data buffer
* @param {NonNegativeInteger} length - number of indexed elements
* @param {integer} stride - stride length
* @param {NonNegativeInteger} offset - index offset
* @returns {ndarray} one-dimensional ndarray
*/
function vector( buffer, length, stride, offset ) {
	return new ndarray( 'float64', buffer, [ length ], [ stride ], offset, 'row-major' );
}

/**
* Returns a zero-dimensional ndarray.
*
* @private
* @param {number} v - scalar value
* @returns {ndarray} zero-dimensional ndarray
*/
function scalar( v ) {
	return scalar2ndarray( v, {
		'dtype': 'generic'
	});
}


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dreplicate, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 1', function test( t ) {
	t.strictEqual( dreplicate.length, 1, 'has expected arity' );
	t.end();
});

tape( 'the function replicates each strided array element', function test( t ) {
	var expected;
	var actual;
	var xbuf;
	var ybuf;
	var out;
	var x;

	xbuf = new Float64Array( [ 1.0, 2.0, 3.0 ] );
	ybuf = new Float64Array( 6 );
	x = vector( xbuf, 3, 1, 0 );
	out = vector( ybuf, 6, 1, 0 );

	actual = dreplicate( [ x, out, scalar( 2 ) ] );
	t.strictEqual( actual, out, 'returns expected value' );

	expected = new Float64Array( [ 1.0, 1.0, 2.0, 2.0, 3.0, 3.0 ] );
	t.strictEqual( isSameFloat64Array( getData( actual ), expected ), true, 'returns expected value' );

	xbuf = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );
	ybuf = new Float64Array( 12 );
	x = vector( xbuf, 4, 1, 0 );
	out = vector( ybuf, 12, 1, 0 );

	actual = dreplicate( [ x, out, scalar( 3 ) ] );
	t.strictEqual( actual, out, 'returns expected value' );

	expected = new Float64Array( [ 1.0, 1.0, 1.0, 2.0, 2.0, 2.0, 3.0, 3.0, 3.0, 4.0, 4.0, 4.0 ] );
	t.strictEqual( isSameFloat64Array( getData( actual ), expected ), true, 'returns expected value' );

	t.end();
});

