tape( 'if the input ndarray is empty, the function returns the output ndarray unchanged', function test( t ) {
	var expected;
	var actual;
	var ybuf;
	var out;
	var x;

	ybuf = new Float64Array( [ 6.0, 7.0, 8.0 ] );
	x = vector( new Float64Array( 0 ), 0, 1, 0 );
	out = vector( ybuf, 3, 1, 0 );

	actual = dreplicate( [ x, out, scalar( 2 ) ] );
	t.strictEqual( actual, out, 'returns expected value' );

	expected = new Float64Array( [ 6.0, 7.0, 8.0 ] );
	t.strictEqual( isSameFloat64Array( getData( actual ), expected ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided a `k` parameter less than or equal to 0, the function returns the output ndarray unchanged', function test( t ) {
	var expected;
	var actual;
	var xbuf;
	var ybuf;
	var out;
	var x;

	xbuf = new Float64Array( [ 1.0, 2.0, 3.0 ] );
	ybuf = new Float64Array( [ 6.0, 7.0, 8.0 ] );
	x = vector( xbuf, 3, 1, 0 );
	out = vector( ybuf, 3, 1, 0 );

	actual = dreplicate( [ x, out, scalar( 0 ) ] );
	t.strictEqual( actual, out, 'returns expected value' );

	expected = new Float64Array( [ 6.0, 7.0, 8.0 ] );
	t.strictEqual( isSameFloat64Array( getData( actual ), expected ), true, 'returns expected value' );

	actual = dreplicate( [ x, out, scalar( -1 ) ] );
	t.strictEqual( actual, out, 'returns expected value' );
	t.strictEqual( isSameFloat64Array( getData( actual ), expected ), true, 'returns expected value' );

	t.end();
});

tape( 'the function supports input ndarrays having non-unit strides', function test( t ) {
	var expected;
	var actual;
	var xbuf;
	var ybuf;
	var out;
	var x;

	xbuf = new Float64Array([
		1.0, // 0
		99.0,
		2.0, // 1
		99.0,
		3.0  // 2
	]);
	ybuf = new Float64Array( 6 );
	x = vector( xbuf, 3, 2, 0 );
	out = vector( ybuf, 6, 1, 0 );

	actual = dreplicate( [ x, out, scalar( 2 ) ] );
	t.strictEqual( actual, out, 'returns expected value' );

	expected = new Float64Array( [ 1.0, 1.0, 2.0, 2.0, 3.0, 3.0 ] );
	t.strictEqual( isSameFloat64Array( getData( actual ), expected ), true, 'returns expected value' );

	t.end();
});

tape( 'the function supports output ndarrays having non-unit strides', function test( t ) {
	var expected;
	var actual;
	var xbuf;
	var ybuf;
	var out;
	var x;

	xbuf = new Float64Array( [ 1.0, 2.0, 3.0 ] );
	ybuf = new Float64Array([
		0.0, // 0
		99.0,
		0.0, // 1
		99.0,
		0.0, // 2
		99.0,
		0.0, // 3
		99.0,
		0.0, // 4
		99.0,
		0.0, // 5
		99.0
	]);
	x = vector( xbuf, 3, 1, 0 );
	out = vector( ybuf, 6, 2, 0 );

	actual = dreplicate( [ x, out, scalar( 2 ) ] );
	t.strictEqual( actual, out, 'returns expected value' );

	expected = new Float64Array( [ 1.0, 99.0, 1.0, 99.0, 2.0, 99.0, 2.0, 99.0, 3.0, 99.0, 3.0, 99.0 ] );
	t.strictEqual( isSameFloat64Array( getData( actual ), expected ), true, 'returns expected value' );

	t.end();
});

tape( 'the function supports negative strides', function test( t ) {
	var expected;
	var actual;
	var xbuf;
	var ybuf;
	var out;
	var x;

	xbuf = new Float64Array([
		1.0, // 2
		2.0, // 1
		3.0  // 0
	]);
	ybuf = new Float64Array([
		0.0, // 5
		0.0, // 4
		0.0, // 3
		0.0, // 2
		0.0, // 1
		0.0  // 0
	]);
	x = vector( xbuf, 3, -1, 2 );
	out = vector( ybuf, 6, -1, 5 );

	actual = dreplicate( [ x, out, scalar( 2 ) ] );
	t.strictEqual( actual, out, 'returns expected value' );

	expected = new Float64Array( [ 1.0, 1.0, 2.0, 2.0, 3.0, 3.0 ] );
	t.strictEqual( isSameFloat64Array( getData( actual ), expected ), true, 'returns expected value' );

	t.end();
});

